    en: "By continuing you agree to the platform terms of use and privacy policy.", lo: "ໂດຍການສືບຕໍ່, ທ່ານຕົກລົງເຫັນດີກັບເງື່ອນໄຂການນໍາໃຊ້ຂອງແພລະຕະຟອມແລະນະໂຍບາຍຄວາມເປັນສ່ວນຕົວ.", km: "តាមរយៈការបន្ត អ្នកយល់ព្រមនឹងលក្ខខណ្ឌនៃការប្រើប្រាស់ និងគោលការណ៍ឯកជនភាពរបស់វេទិកា។", my: "ဆက်လက်လုပ်ဆောင်ခြင်းဖြင့် သင်သည် ပလပ်ဖောင်းအသုံးပြုမှုစည်းမျဉ်းများနှင့် ကိုယ်ရေးကိုယ်တာမူဝါဒများကို သဘောတူပါသည်။"
