    en: "Only Association Admins can add, edit, or delete members and companies. Contact your administrator if you need access.", lo: "ມີພຽງແຕ່ຜູ້ເບິ່ງແຍງສະມາຄົມທີ່ສາມາດເພີ່ມ, ແກ້ໄຂ, ຫຼືລຶບສະມາຊິກ ແລະບໍລິສັດໄດ້. ຕິດຕໍ່ຜູ້ເບິ່ງແຍງລະບົບຂອງທ່ານຖ້າທ່ານຕ້ອງການການເຂົ້າເຖິງ.", km: "មានតែអ្នកគ្រប់គ្រងសមាគមប៉ុណ្ណោះដែលអាចបន្ថែម កែសម្រួល ឬលុបសមាជិក និងក្រុមហ៊ុនបាន។ ទាក់ទងអ្នកគ្រប់គ្រងរបស់អ្នក ប្រសិនបើអ្នកត្រូវការចូលប្រើ។", my: "Association Admins များသာလျှင် အဖွဲ့ဝင်များနှင့် ကုမ္ပဏီများကို ထည့်ခြင်း၊ တည်းဖြတ်ခြင်း သို့မဟုတ် ဖျက်နိုင်ပါသည်။ သင်ဝင်ရောက်ခွင့်လိုအပ်ပါက သင့်စီမံခန့်ခွဲသူကို ဆက်သွယ်ပါ။"
