    en: "This action cannot be undone. The listing and all related data will be permanently removed.", lo: "ຄຳສັ່ງນີ້ບໍ່ສາມາດຍົກເລີກໄດ້. ລາຍຊື່ ແລະຂໍ້ມູນທີ່ກ່ຽວຂ້ອງທັງໝົດຈະຖືກລຶບອອກຖາວອນ.", km: "សកម្មភាពនេះមិនអាចត្រឡប់វិញបានទេ។ ការចុះបញ្ជី និងទិន្នន័យពាក់ព័ន្ធទាំងអស់នឹងត្រូវដកចេញជាអចិន្ត្រៃយ៍។", my: "ဤလုပ်ဆောင်ချက်ကို ပြန်ပြင်၍မရပါ။ စာရင်းနှင့် ဆက်စပ်ဒေတာအားလုံးကို အပြီးတိုင် ဖယ်ရှားပါမည်။"
