    en: "This action cannot be undone. All selected listings and related data will be permanently removed.", lo: "ຄຳສັ່ງນີ້ບໍ່ສາມາດຍົກເລີກໄດ້. ລາຍຊື່ທີ່ເລືອກທັງໝົດ ແລະຂໍ້ມູນທີ່ກ່ຽວຂ້ອງຈະຖືກລຶບອອກຖາວອນ.", km: "សកម្មភាពនេះមិនអាចត្រឡប់វិញបានទេ។ បញ្ជីដែលបានជ្រើសរើសទាំងអស់ និងទិន្នន័យដែលពាក់ព័ន្ធនឹងត្រូវដកចេញជាអចិន្ត្រៃយ៍។", my: "ဤလုပ်ဆောင်ချက်ကို ပြန်ပြင်၍မရပါ။ ရွေးချယ်ထားသော စာရင်းများနှင့် ဆက်စပ်ဒေတာအားလုံးကို အပြီးတိုင် ဖယ်ရှားပါမည်။"
