  "mk.qs.cancel.confirm.title": { vi: "Huỷ yêu cầu báo giá?", en: "Cancel quote request?" , lo: "ຍົກເລີກຄຳຮ້ອງຂໍໃບສະເໜີລາຄາບໍ?", km: "បោះបង់សំណើសម្រង់ឬ?", my: "ကိုးကားတောင်းဆိုမှုကို ပယ်ဖျက်မလား။" },
  "mk.qs.cancel.confirm.desc": {
    vi: "Hành động này không thể hoàn tác. Người bán sẽ không còn thấy yêu cầu này và bạn sẽ cần gửi lại từ đầu nếu muốn tiếp tục.",
    en: "This action cannot be undone. The seller will no longer see this request and you will need to submit a new one if you wish to continue.", lo: "ຄຳສັ່ງນີ້ບໍ່ສາມາດຍົກເລີກໄດ້. ຜູ້ຂາຍຈະບໍ່ເຫັນຄໍາຮ້ອງຂໍນີ້ອີກຕໍ່ໄປແລະທ່ານຈະຕ້ອງສົ່ງຄໍາຮ້ອງຂໍໃຫມ່ຖ້າທ່ານຕ້ອງການສືບຕໍ່.", km: "សកម្មភាពនេះមិនអាចត្រឡប់វិញបានទេ។ អ្នកលក់នឹងលែងឃើញសំណើនេះទៀតហើយ ហើយអ្នកនឹងត្រូវដាក់ស្នើថ្មីប្រសិនបើអ្នកចង់បន្ត។", my: "ဤလုပ်ဆောင်ချက်ကို ပြန်ပြင်၍မရပါ။ ရောင်းချသူသည် ဤတောင်းဆိုချက်ကို မတွေ့ရတော့ဘဲ ဆက်လက်လုပ်ဆောင်လိုပါက အသစ်တစ်ခုကို တင်သွင်းရန် လိုအပ်မည်ဖြစ်သည်။"
  },
  "mk.qs.cancel.confirm.keep": { vi: "Giữ lại yêu cầu", en: "Keep request" , lo: "ຮັກສາການຮ້ອງຂໍ", km: "រក្សាការស្នើសុំ", my: "တောင်းဆိုမှုကို သိမ်းဆည်းပါ။" },
  "mk.qs.cancel.confirm.confirm": { vi: "Xác nhận huỷ", en: "Confirm cancel" , lo: "ຢືນຢັນການຍົກເລີກ", km: "បញ្ជាក់ការលុបចោល", my: "ပယ်ဖျက်ကြောင်းအတည်ပြုပါ။" },
  "mk.qs.cancel.reason.label": { vi: "Lý do huỷ (bắt buộc)", en: "Cancellation reason (required)" , lo: "ເຫດຜົນການຍົກເລີກ (ຕ້ອງການ)", km: "ហេតុផលនៃការលុបចោល (ចាំបាច់)", my: "ပယ်ဖျက်ရခြင်းအကြောင်းအရင်း (လိုအပ်သည်)" },
