  "mk.ws.title": { vi: "Không gian của tôi", en: "My workspace" , lo: "ພື້ນທີ່ເຮັດວຽກຂອງຂ້ອຍ", km: "កន្លែងធ្វើការរបស់ខ្ញុំ", my: "ငါ့အလုပ်ခွင်" },
