  "mk.ws.identityDesc": {
    vi: "Tài khoản của bạn chưa được liên kết hồ sơ hội viên nên không thể hiển thị dữ liệu cá nhân.",
    en: "Your account is not linked to a member profile, so personal data cannot be shown.", lo: "ບັນຊີຂອງທ່ານບໍ່ໄດ້ເຊື່ອມໂຍງກັບໂປຣໄຟລ໌ສະມາຊິກ, ດັ່ງນັ້ນຂໍ້ມູນສ່ວນຕົວບໍ່ສາມາດສະແດງໄດ້.", km: "គណនីរបស់អ្នកមិនត្រូវបានភ្ជាប់ទៅកម្រងព័ត៌មានសមាជិកទេ ដូច្នេះទិន្នន័យផ្ទាល់ខ្លួនមិនអាចត្រូវបានបង្ហាញបានទេ។", my: "သင့်အကောင့်သည် အဖွဲ့ဝင်ပရိုဖိုင်နှင့် လင့်ခ်မချိတ်ထားသောကြောင့် ကိုယ်ရေးကိုယ်တာအချက်အလက်များကို ပြသ၍မရပါ။"
  },

  "mk.chat.prefill": {
    vi: 'Chào bạn, mình quan tâm tới sản phẩm "{title}" ({price}) trên Marketplace. Bạn có thể tư vấn thêm giúp mình không?',
    en: 'Hi, I\'m interested in your listing "{title}" ({price}) on the Marketplace. Could you share more details?', lo: "ສະບາຍດີ, ຂ້ອຍສົນໃຈລາຍການຂອງເຈົ້າ \"{title}\" ({price}) ຢູ່ໃນຕະຫຼາດ. ເຈົ້າສາມາດແບ່ງປັນລາຍລະອຽດເພີ່ມເຕີມໄດ້ບໍ?", km: "សួស្តី ខ្ញុំចាប់អារម្មណ៍លើការចុះបញ្ជីរបស់អ្នក \"{title}\" ({price}) នៅលើទីផ្សារ។ តើអ្នកអាចចែករំលែកព័ត៌មានលម្អិតបន្ថែមបានទេ?", my: "မင်္ဂလာပါ၊ Marketplace ရှိ သင်၏စာရင်း \"{title}\" ({price}) ကို စိတ်ဝင်စားပါသည်။ နောက်ထပ်အသေးစိတ်အချက်အလက်များကို မျှဝေနိုင်ပါသလား။"
  },
